// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

import org.eclipse.rdf4j.common.iteration.QueryExecutionDeadline;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

/**
 * The managed growth driver reserves replacement snapshots for parked replay attempts during
 * {@link LmdbSailStore.GrowthPhase#RESERVE_REPLAYS}. A parked attempt may close concurrently (its query failed or its
 * connection closed) after the driver's pre-check but before the fresh view registers for admission. The driver owns
 * the closed episode, so waiting for admission there can never be satisfied: the episode stays closed and every later
 * writer, including the store's own shutdown flush, waits forever.
 */
class LmdbReplayReservationCloseRaceTest {
	private static final LmdbSailStore.MapGrowthObserver NO_REPLAY = (kind, token, deadlineNanos, attempts,
			views) -> false;

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void growthDriverDoesNotWaitForItsOwnEpisodeWhenAParkedAttemptCloses(@TempDir Path dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(64L * 1024 * 1024)
				.setValueDBSize(1024L * 1024)
				.setMapGrowthReadDrainTimeoutMillis(0)
				.setAutoGrow(true);
		AtomicReference<LmdbSailStore.ReadAttemptLease> closeOnReservation = new AtomicReference<>();
		AtomicReference<Thread> driver = new AtomicReference<>();
		AtomicInteger closedDuringReservation = new AtomicInteger();
		LmdbSailStore backing = new LmdbSailStore(dataDir.toFile(), new StoreProperties(dataDir.toFile()), config,
				false, ValueStore::new, TripleStore::new) {
			@Override
			void beforeGrowthAdmissionDeadlineCheck(QueryExecutionDeadline deadline) {
				if (!Thread.currentThread().getName().startsWith("LmdbMapGrowth-")
						|| growthMetricsSnapshot().currentPhase() != LmdbSailStore.GrowthPhase.RESERVE_REPLAYS) {
					return;
				}
				driver.set(Thread.currentThread());
				// The driver has passed its "attempt still open" pre-check and is now registering the fresh view:
				// close the parked attempt exactly here, as a failing replay or a closing connection would.
				LmdbSailStore.ReadAttemptLease parked = closeOnReservation.getAndSet(null);
				if (parked != null) {
					parked.close();
					closedDuringReservation.incrementAndGet();
				}
			}
		};
		LmdbSailStore.MapGrowthObserver acceptingReplay = (kind, token, deadlineNanos, attempts, views) -> {
			for (LmdbSailStore.ReadViewLease view : views) {
				view.retireNativeSnapshots(kind);
			}
			return true;
		};
		Object writerOwner = new Object();
		try (LmdbSailStore.ReadAttemptLease writer = backing.registerReadAttempt(writerOwner, NO_REPLAY);
				LmdbSailStore.ReadAttemptLease reader = backing.registerReadAttempt(acceptingReplay)) {
			writer.markWriteIntent();
			try (LmdbSailStore.ReadView view = backing.createTransactionReadView(acceptingReplay, reader);
					LmdbSailStore.MapGrowthAttempt warning = backing.beginMapGrowthWarning(writerOwner)) {
				TripleStore triples = backing.getTripleStore();
				long acceptedBefore = backing.growthMetricsSnapshot().replayAccepted();
				try (LmdbSailStore.MapGrowthAttempt emergency = backing.beginMapGrowthAttempt(writerOwner)) {
					emergency.requestQuiescence(LmdbSailStore.MapResizeKind.TRIPLE_STORE);
					assertTrue(triples.growMapForEstimatedWrite(triples.mapSizeBytes() * 2L, emergency));
				}
				assertEquals(acceptedBefore + 1, backing.growthMetricsSnapshot().replayAccepted(),
						"The reader's accepted replay parks its attempt in the managed episode");
				closeOnReservation.set(reader);
				warning.close();
				writer.completeTransaction();
				awaitGrowthPhase(backing, LmdbSailStore.GrowthPhase.OPEN);
				assertEquals(1, closedDuringReservation.get(),
						"The parked attempt must have closed while the driver reserved its replacement");
				assertFalse(backing.growthAdmissionClosed(),
						"A parked attempt that closes during reservation must not keep the episode closed");
				try (LmdbSailStore.ReadAttemptLease late = backing.registerReadAttempt(NO_REPLAY)) {
					assertFalse(late.isClosed());
				}
			} finally {
				writer.completeTransaction();
			}
		} finally {
			Thread stuck = driver.get();
			if (stuck != null
					&& backing.growthMetricsSnapshot().currentPhase() == LmdbSailStore.GrowthPhase.RESERVE_REPLAYS) {
				// Only reached when the driver is self-deadlocked: unblock it so the store can still close.
				stuck.interrupt();
			}
			backing.close();
		}
	}

	private static void awaitGrowthPhase(LmdbSailStore backing, LmdbSailStore.GrowthPhase expected) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
		while (backing.growthMetricsSnapshot().currentPhase() != expected && System.nanoTime() < deadline) {
			Thread.onSpinWait();
		}
		assertEquals(expected, backing.growthMetricsSnapshot().currentPhase(),
				"The growth driver must finish reserving replays and reopen admission");
	}
}
